-- 316: SG header contact bar — drop "Call"/"Email:" labels, use email icon (ic-letter)
-- and a WhatsApp icon + number in place of the raw wa.me URL.
-- Scoped to the SG header phone block only: identifier block_header_top_left carrying the
-- SG hotline 61000613. MY/GH partner DBs hold a different number in that identifier, so
-- their blocks never match. UNHEX() carries the exact HTML to dodge apply.php's semicolon
-- splitter and backslash/quote escaping.
UPDATE cms_block
SET content = UNHEX('')
WHERE identifier = 'block_header_top_left'
  AND content LIKE '%61000613%';
